#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll val;
    int idx;
} Pair;

int cmp(const void *a, const void *b) {
    Pair *pa = (Pair*)a;
    Pair *pb = (Pair*)b;
    if (pa->val != pb->val) return pa->val < pb->val ? -1 : 1;
    return pa->idx - pb->idx;
}

int bit[200005];
int n;

void update(int i, int delta) {
    for (; i <= n+1; i += i & -i)
        bit[i] += delta;
}

int query(int i) {
    int s = 0;
    for (; i > 0; i -= i & -i)
        s += bit[i];
    return s;
}

int main() {
    int K;
    scanf("%d %d", &n, &K);
    int a[200005];
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }

    // prefix sums S_i = sum_{j=1..i} (a_j - K)
    ll S[200005];
    S[0] = 0;
    for (int i = 1; i <= n; i++) {
        S[i] = S[i-1] + (a[i] - K);
    }

    // coordinate compression
    Pair pts[200005];
    for (int i = 0; i <= n; i++) {
        pts[i].val = S[i];
        pts[i].idx = i;
    }
    qsort(pts, n+1, sizeof(Pair), cmp);

    int rank[200005];
    int r = 1;
    rank[pts[0].idx] = r;
    for (int i = 1; i <= n; i++) {
        if (pts[i].val != pts[i-1].val) r++;
        rank[pts[i].idx] = r;
    }

    ll ans = 0;
    for (int i = 0; i <= n; i++) {
        ans += query(rank[i]);
        update(rank[i], 1);
    }

    printf("%lld\n", ans);
    return 0;
}

