// We need to count pairs (i,j) with i<=j such that
// (a[i] + a[i+1] + ... + a[j]) / (j-i+1) >= K
// Equivalently, sum of (a[k] - K) >= 0 for k from i to j
// Let b[k] = a[k] - K, then we need prefix sums where prefix[j] - prefix[i-1] >= 0
// i.e., prefix[j] >= prefix[i-1]
// Count pairs (i,j) 0<=i<j<=N (using 0-indexed prefix array of size N+1)
// where prefix[j] >= prefix[i]
// This is equivalent to counting inversions in reverse, i.e., count pairs where prefix[j] >= prefix[i] for j > i

// We can use merge sort to count pairs where prefix[j] >= prefix[i] (j > i)
// Total pairs - pairs where prefix[j] < prefix[i]

#include <string.h>

long long merge_count(long long *arr, long long *temp, int left, int right) {
    if (left >= right) return 0;
    int mid = (left + right) / 2;
    long long count = 0;
    count += merge_count(arr, temp, left, mid);
    count += merge_count(arr, temp, mid+1, right);

    // Count pairs where arr[i] > arr[j] (i in left half, j in right half)
    // These are pairs where prefix[j] < prefix[i], i.e., bad pairs
    int i = left, j = mid+1;
    long long inv = 0;
    // For each j in right half, count i in left half where arr[i] > arr[j]
    // Since left half is sorted, use two pointers
    int ptr = left;
    for (j = mid+1; j <= right; j++) {
        while (ptr <= mid && arr[ptr] <= arr[j]) ptr++;
        inv += (mid - ptr + 1);
    }
    count += inv;

    // Merge
    i = left; j = mid+1;
    int k = left;
    while (i <= mid && j <= right) {
        if (arr[i] <= arr[j]) temp[k++] = arr[i++];
        else temp[k++] = arr[j++];
    }
    while (i <= mid) temp[k++] = arr[i++];
    while (j <= right) temp[k++] = arr[j++];
    for (i = left; i <= right; i++) arr[i] = temp[i];

    return count;
}

int main() {
    int n, K;
    scanf("%d %d", &n, &K);

    long long *prefix = (long long*)malloc((n+1) * sizeof(long long));
    long long *temp = (long long*)malloc((n+1) * sizeof(long long));

    prefix[0] = 0;
    for (int i = 1; i <= n; i++) {
        long long a;
        scanf("%lld", &a);
        prefix[i] = prefix[i-1] + (a - K);
    }

    long long total = (long long)n * (n+1) / 2;
    // Count bad pairs: prefix[j] < prefix[i] for j > i
    long long bad = merge_count(prefix, temp, 0, n);

    printf("%lld\n", total - bad);

    free(prefix);
    free(temp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll *bit;
    int n;
} Fenwick;

void bit_add(Fenwick *fw, int idx, ll val) {
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

ll bit_sum(Fenwick *fw, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += fw->bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int lower_bound_ll(ll *arr, int n, ll x) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N;
    ll K;
    if (scanf("%d %lld", &N, &K) != 2) return 0;

    ll *pref = (ll *)malloc((N + 1) * sizeof(ll));
    ll *vals = (ll *)malloc((N + 1) * sizeof(ll));
    pref[0] = 0;

    for (int i = 1; i <= N; i++) {
        ll a;
        scanf("%lld", &a);
        pref[i] = pref[i - 1] + (a - K);
    }

    for (int i = 0; i <= N; i++) vals[i] = pref[i];
    qsort(vals, N + 1, sizeof(ll), cmp_ll);

    int m = 0;
    for (int i = 0; i <= N; i++) {
        if (i == 0 || vals[i] != vals[i - 1]) {
            vals[m++] = vals[i];
        }
    }

    Fenwick fw;
    fw.n = m;
    fw.bit = (ll *)calloc(m + 1, sizeof(ll));

    ll ans = 0;
    for (int i = 0; i <= N; i++) {
        int pos = lower_bound_ll(vals, m, pref[i]) + 1; // 1-based
        ans += bit_sum(&fw, pos);
        bit_add(&fw, pos, 1);
    }

    printf("%lld\n", ans);

    free(pref);
    free(vals);
    free(fw.bit);
    return 0;
}

