    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        a[i] -= k; // subtract k from each element
    }

    // Now we need to count subarrays with sum >= 0
    // prefix sum approach with merge sort / BIT

    // prefix[i] = a[0] + ... + a[i-1]
    // sum(l, r) = prefix[r+1] - prefix[l] >= 0
    // => prefix[r+1] >= prefix[l]
    // Count pairs (l, r) with l < r+1 where prefix[r+1] >= prefix[l]
    // i.e., for each j from 1 to n, count i < j where prefix[i] <= prefix[j]

    vector<long long> prefix(n + 1);
    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + a[i];
    }

    // Count inversions (pairs where prefix[i] > prefix[j] for i < j) using merge sort
    // Total pairs = n*(n+1)/2
    // Answer = total pairs - number of pairs (i,j) with i<j and prefix[i] > prefix[j]

    // Actually let's count directly: pairs (i,j) with i < j and prefix[j] >= prefix[i]
    // Use merge sort to count

    long long count = 0;

    // Merge sort count
    vector<long long> temp(n + 1);

    function<void(int, int)> mergeSort = [&](int left, int right) {
        if (right - left <= 1) return;
        int mid = (left + right) / 2;
        mergeSort(left, mid);
        mergeSort(mid, right);

        // Count pairs where prefix[i] <= prefix[j], i in [left,mid), j in [mid,right)
        int j = mid;
        for (int i = left; i < mid; i++) {
            while (j < right && prefix[j] < prefix[i]) j++;
            count += (right - j);
        }

        // Merge
        int i = left, k = mid, idx = left;
        while (i < mid && k < right) {
            if (prefix[i] <= prefix[k]) {
                temp[idx++] = prefix[i++];
            } else {
                temp[idx++] = prefix[k++];
            }
        }
        while (i < mid) temp[idx++] = prefix[i++];
        while (k < right) temp[idx++] = prefix[k++];
        for (int x = left; x < right; x++) prefix[x] = temp[x];
    };

    mergeSort(0, n + 1);

    cout << count << endl;

    return 0;
}

