int64 countNonInversions(vector<int64>& arr) {
    vector<int64> sorted = arr;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());

    int m = sorted.size();
    vector<int> bit(m + 1, 0);

    auto add = [&](int idx, int val) {
        for (++idx; idx <= m; idx += idx & -idx)
            bit[idx] += val;
    };

    auto sum = [&](int idx) {
        int64 res = 0;
        for (++idx; idx > 0; idx -= idx & -idx)
            res += bit[idx];
        return res;
    };

    int64 count = 0;
    for (int64 x : arr) {
        int pos = lower_bound(sorted.begin(), sorted.end(), x) - sorted.begin();
        count += sum(pos); // count how many <= x seen so far
        add(pos, 1);
    }
    return count;
}

