    for (int i = 1; i <= N; ++i) {
        ll x;
        cin >> x;
        pref[i] = pref[i - 1] + (x - K);
    }

    // We need count of pairs (l, r) with l < r and pref[r] >= pref[l]
    // Coordinate compress prefix sums
    vector<ll> vals = pref;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    Fenwick fw((int)vals.size());
