import java.util.*;
import java.io.*;

public class Main {
    static long invCount = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long K = Long.parseLong(st.nextToken());

        long[] a = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            a[i] = Long.parseLong(st.nextToken()) - K;
        }

        // prefix sums: prefix[0] = 0, prefix[i] = a[0]+...+a[i-1]
        long[] prefix = new long[N + 1];
        prefix[0] = 0;
        for (int i = 0; i < N; i++) {
            prefix[i + 1] = prefix[i] + a[i];
        }

        // Count pairs (l, r) with l < r and prefix[r] >= prefix[l]
        // = total pairs - pairs where prefix[r] < prefix[l]
        // pairs where prefix[r] < prefix[l] = inversions in prefix array

        invCount = 0;
        mergeSort(prefix, 0, N);

        long total = (long)(N + 1) * N / 2;
        long answer = total - invCount;

        System.out.println(answer);
    }

    // Count inversions: pairs (i,j) with i<j and arr[i] > arr[j]
    static long[] temp;

    static void mergeSort(long[] arr, int left, int right) {
        if (temp == null) temp = new long[arr.length];
        if (left >= right) return;
        int mid = (left + right) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }

    static void merge(long[] arr, int left, int mid, int right) {
        int i = left, j = mid + 1, k = left;
        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                // arr[i] > arr[j]: all elements from i to mid are > arr[j]
                invCount += (mid - i + 1);
                temp[k++] = arr[j++];
            }
        }
        while (i <= mid) temp[k++] = arr[i++];
        while (j <= right) temp[k++] = arr[j++];
        for (int x = left; x <= right; x++) arr[x] = temp[x];
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fenwick Tree / BIT for prefix sums of frequencies
    static class Fenwick {
        int n;
        long[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new long[n + 2];
        }

        void add(int idx, long val) {
            while (idx <= n) {
                bit[idx] += val;
                idx += idx & -idx;
            }
        }

        long sum(int idx) {
            long res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long K = fs.nextLong();

        long[] pref = new long[N + 1];
        pref[0] = 0;

        for (int i = 1; i <= N; i++) {
            long a = fs.nextLong();
            pref[i] = pref[i - 1] + (a - K);
        }

        // We need count of pairs (l-1, r) with pref[r] >= pref[l-1]
        // i.e. number of pairs i < j with pref[i] <= pref[j]
        long[] vals = pref.clone();
        Arrays.sort(vals);

        // coordinate compression
        long[] uniq = new long[N + 1];
        int m = 0;
        for (int i = 0; i <= N; i++) {
            if (i == 0 || vals[i] != vals[i - 1]) {
                uniq[m++] = vals[i];
            }
        }

        Fenwick fw = new Fenwick(m);
        long ans = 0;

        for (int i = 0; i <= N; i++) {
            int idx = lowerBound(uniq, m, pref[i]) + 1; // 1-based
            ans += fw.sum(idx); // count previous prefix sums <= current
            fw.add(idx, 1);
        }

        System.out.println(ans);
    }

    static int lowerBound(long[] a, int len, long key) {
        int l = 0, r = len;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] < key) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
